// Types used by the C++ generated by dataclass-native
#pragma once

#include <chrono>
#include <compare>
#include <cstdint>
#include <memory>
#include <stdexcept>
#include <utility>
#include <vector>

namespace dataclass_native
{
    using Bytes = std::vector<std::uint8_t>;

    // datetime.date
    using Date = std::chrono::sys_days;

    // A timezone-aware datetime.datetime: an instant, as microseconds since the epoch, UTC
    using DateTime = std::chrono::sys_time<std::chrono::microseconds>;

    // datetime.timedelta
    using TimeDelta = std::chrono::microseconds;

    // datetime.time, without a timezone (a type of its own, as serialised differently from a TimeDelta)
    struct TimeOfDay
    {
        std::chrono::microseconds since_midnight{};

        friend auto operator<=>(const TimeOfDay&, const TimeOfDay&) = default;
    };

    // Shared[T]: an immutable value, shared rather than copied, and compared by value (as Rust's Arc<T>).
    // Only a default-constructed or moved-from Shared is empty.
    template <class T>
    class Shared
    {
    public:
        Shared() = default;

        Shared(T value) : ptr_(std::make_shared<const T>(std::move(value)))
        {
        }

        explicit Shared(std::shared_ptr<const T> ptr) : ptr_(std::move(ptr))
        {
        }

        const T& operator*() const
        {
            return *get();
        }

        const T* operator->() const
        {
            return get();
        }

        const T* get() const
        {
            if (!ptr_)
                throw std::logic_error("dataclass_native::Shared is empty");
            return ptr_.get();
        }

        const std::shared_ptr<const T>& ptr() const
        {
            return ptr_;
        }

        explicit operator bool() const
        {
            return static_cast<bool>(ptr_);
        }

        friend bool operator==(const Shared& lhs, const Shared& rhs)
        {
            if (lhs.ptr_ == rhs.ptr_)
                return true;
            if (!lhs.ptr_ || !rhs.ptr_)
                return false;
            return *lhs.ptr_ == *rhs.ptr_;
        }

    private:
        std::shared_ptr<const T> ptr_;
    };

    // A value stored out of line, so that recursive types are possible: copied deeply and compared by value (as
    // C++26's std::indirect, or Rust's Box<T>). Unlike std::indirect, it is empty when default-constructed, so that
    // default-constructing a recursive type terminates.
    template <class T>
    class Indirect
    {
    public:
        Indirect() = default;

        Indirect(T value) : ptr_(std::make_unique<T>(std::move(value)))
        {
        }

        Indirect(const Indirect& other) : ptr_(other.ptr_ ? std::make_unique<T>(*other.ptr_) : nullptr)
        {
        }

        Indirect(Indirect&&) noexcept = default;

        Indirect& operator=(const Indirect& other)
        {
            if (this != &other)
                ptr_ = other.ptr_ ? std::make_unique<T>(*other.ptr_) : nullptr;
            return *this;
        }

        Indirect& operator=(Indirect&&) noexcept = default;

        ~Indirect() = default;

        T& operator*()
        {
            return *get();
        }

        const T& operator*() const
        {
            return *get();
        }

        T* operator->()
        {
            return get();
        }

        const T* operator->() const
        {
            return get();
        }

        T* get() const
        {
            if (!ptr_)
                throw std::logic_error("dataclass_native::Indirect is empty");
            return ptr_.get();
        }

        explicit operator bool() const
        {
            return static_cast<bool>(ptr_);
        }

        friend bool operator==(const Indirect& lhs, const Indirect& rhs)
        {
            if (!lhs.ptr_ || !rhs.ptr_)
                return !lhs.ptr_ && !rhs.ptr_;
            return *lhs.ptr_ == *rhs.ptr_;
        }

    private:
        std::unique_ptr<T> ptr_;
    };
} // namespace dataclass_native
